        performanceOpen:false,chartTimer:null,queueForecastCharts(){clearTimeout(this.chartTimer);this.chartTimer=setTimeout(()=>{if(this.tab==='overview'&&this.performanceOpen)this.renderCharts();if(this.tab==='actuals')this.renderActualChart();},150);},
        sensitivity:100,get sensitivityResult(){const sf=this.scenFactors(this.scenario);return this.buildModel({...sf,cpv:sf.cpv*this.sensitivity/100}).totals;},
        level:'basic',flow:'budget',savingsOpen:false,autosave:true,draftTimer:null,versions:[],versionComparison:null,projectId:@js((string)($payload['project_id']??'')),campaignId:@js((string)($payload['campaign_id']??'')),shareDays:7,shareUrl:'',reportBrandId:'',
        reportBrands:@js(auth()->user()->canInWorkspace(app('current_workspace'),'links.view') ? \App\Modules\User\Models\BrandKit::where('user_id',workspace_owner_id())->get()->map(fn($b)=>['id'=>$b->id,'name'=>$b->name,'color'=>$b->palette()['primary']??'#3454ef']) : collect()),
        inputOrigin(key){const origin=this.p.assumption_origins?.[key];return !origin?'Assumed · editable':origin.value===JSON.stringify(this.p[key])?origin.kind:'Manually edited';},
        recordOrigins(keys,kind){this.p.assumption_origins=this.p.assumption_origins||{};for(const k of keys)this.p.assumption_origins[k]={kind,value:JSON.stringify(this.p[k])};},
        get period(){return Math.max(1,Math.min(12,this.n(this.p.period_months)||12));},
        premiumInit(){this.p.period_months=this.p.period_months||12;this.p.costs=Array.isArray(this.p.costs)?this.p.costs:[];for(const k of ['sales_delay','repeat_rate','refund_rate','churn_rate'])this.p[k]=Math.max(0,this.n(this.p[k]));},
        channelBudget(c,budget){let n=Math.max(this.n(c.min_budget),budget*this.n(c.alloc)/100);if(this.n(c.max_budget)>0)n=Math.min(n,this.n(c.max_budget));return n;},
        get allocationWarning(){const n=this.sum(this.p.channels.filter(c=>!c.fixed).map(c=>this.n(c.alloc)));return Math.abs(n-100)>.01?'Channel allocations total '+this.nf(n,1)+'%. Adjust them to 100%; floors and ceilings may also change actual spend.':'';},
        addChannel(){this.p.channels.push({key:'custom_'+Date.now(),name:'Custom channel',fixed:false,alloc:0,cpv:100,vl:3,lc:10,acv:1000,notes:'User assumption'});},
        addCost(){this.p.costs.push({name:'Additional cost',amount:0,frequency:'monthly',month:0});},
        saveScenario(){const label=prompt('Name this scenario');if(!label?.trim())return;const key='custom_'+Date.now();this.p.scenarios[key]={...this.scenFactors(this.scenario)};for(const f of ['cpv','vl','lc','budget'])this.p.scenarios[key][f]*=100;this.p.scenario_labels=this.p.scenario_labels||{};this.p.scenario_labels[key]=label.trim().slice(0,60);this.scenKeys.push(key);this.scenLabels[key]=this.p.scenario_labels[key];this.scenario=key;},
        scheduleDraft(){clearTimeout(this.draftTimer);if(!this.autosave||!this.planId||!this.dirty||this.saving)return;this.draftTimer=setTimeout(()=>this.save(true),1800);},
        async forecastRequest(path,method='GET',body=null){const res=await fetch(path,{method,headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]')?.content,'X-Requested-With':'XMLHttpRequest'},...(body?{body:JSON.stringify(body)}:{})});const j=await res.json().catch(()=>({}));if(!res.ok)throw Error(j.message||'Could not complete the request.');return j;},
        forecastPath(action){return @js(url('/user/marketing-plan'))+'/'+this.planId+'/'+action;},
        async loadVersions(){if(!this.planId){this.saveError='Save the forecast first.';return;}try{this.versions=(await this.forecastRequest(this.forecastPath('versions'))).versions;}catch(e){this.saveError=e.message;}},
        compareVersion(v){const source=typeof v.payload==='string'?JSON.parse(v.payload):v.payload;this.versionComparison={name:v.name,totals:this.buildModel(this.scenFactors(this.scenario),null,source).totals};},
        async restoreVersion(v){if(!confirm('Restore these assumptions? Your actuals and existing connections are kept.'))return;try{const j=await this.forecastRequest(this.forecastPath('versions/'+v.id+'/restore'),'POST',{});this.name=j.name;this.p=j.payload;this.premiumInit();this.scenario='expected';this.scenKeys=['conservative','expected','aggressive'];this.scenLabels={conservative:'Conservative',expected:'Expected',aggressive:'Aggressive'};for(const [key,label] of Object.entries(this.p.scenario_labels||{})){if(this.p.scenarios?.[key]&&this.scenKeys.length<8){this.scenKeys.push(key);this.scenLabels[key]=label;}}this._baseline=this.snapshot();this.dirty=false;this.savedFlash=true;}catch(e){this.saveError=e.message;}},
        async connectForecast(action){if(!this.planId){this.saveError='Save the forecast first.';return;}try{if(this.dirty&&!await this.save(true))return;const j=await this.forecastRequest(this.forecastPath('connect'),'POST',{action,project_id:this.projectId||null,campaign_id:this.campaignId||null});this.dirty=false;window.location.href=j.redirect;}catch(e){this.saveError=e.message;}},
        async shareForecast(){if(!this.planId){this.saveError='Save the forecast first.';return;}try{if(this.dirty&&!await this.save(true))return;this.shareUrl=(await this.forecastRequest(this.forecastPath('share'),'POST',{days:this.shareDays,brand_kit_id:this.reportBrandId||null})).url;}catch(e){this.saveError=e.message;}},
        async revokeShares(){if(!this.planId)return;try{await this.forecastRequest(this.forecastPath('share'),'DELETE');this.shareUrl='';this.savedFlash=true;}catch(e){this.saveError=e.message;}},
        @include('user.marketing-plan.assist-script')
